const projects=[
{label:'01 / INDEPENDENT PROJECT · JAN–MAR 2026',title:'A connected view of restaurant operations.',context:'Red Pepper Pizzeria & Pasta · Carnation, Washington',question:'How can orders, recipes, and inventory connect to support useful operational reporting?',approach:['Designed a relational schema linking orders, menu items, recipes, ingredients, and inventory.','Wrote example SQL queries for revenue, order activity, and menu performance.','Designed ingredient-usage comparisons to support waste analysis.'],takeaway:'The project brings transaction data and ingredient data into a shared structure, creating a foundation for asking better operational questions.',note:'This overview is based on my resume. The diagram is a conceptual illustration, not the original database schema. Source queries and project files are not included.'},
{label:'02 / INDEPENDENT PROJECT · JAN–FEB 2026',title:'Understanding what moves profit.',context:'Red Pepper Pizzeria & Pasta · Carnation, Washington',question:'How could changes in ingredient costs and waste affect monthly profit?',approach:['Interviewed a manager/owner to understand the business context.','Built a dashboard tracking revenue, order volume, profit margins, and cost distribution.','Built a sensitivity model estimating how ingredient costs and waste reduction could affect monthly profit.'],takeaway:'The project connects a business conversation with a dashboard and a model for exploring operational tradeoffs.',note:'The project modeled possible effects; it does not claim realized savings or measured profit improvements. The cover is a conceptual illustration.'},
{label:'03 / INDEPENDENT PROJECT · NOV–DEC 2025',title:'Seeing beyond the register.',context:'Habibi Tacos · Washington',question:'What can sales and operations data reveal when paired with firsthand customer-facing experience?',approach:['Built an Excel dashboard visualizing revenue trends, customer volume, and operational performance.','Applied firsthand cashier experience to examine customer demand and order activity.','Analyzed relationships between customer demand, order activity, and operating costs.'],takeaway:'The project pairs firsthand experience with structured analysis to better understand the daily rhythm of a business.',note:'The cover chart is illustrative and does not represent actual business data. The original Excel workbook is not included.'}
];
const dialog=document.querySelector('#project-dialog');
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const p=projects[Number(button.dataset.project)];document.querySelector('#dialog-content').innerHTML=`<span class="micro">${p.label}</span><h2 id="dialog-title">${p.title}</h2><p>${p.context}</p><h3>The question</h3><p>${p.question}</p><h3>What I built</h3><ul>${p.approach.map(x=>`<li>${x}</li>`).join('')}</ul><h3>The perspective</h3><p>${p.takeaway}</p><p class="dialog-note">${p.note}</p><a class="dialog-link" href="mailto:younus.koronfel622@gmail.com?subject=${encodeURIComponent('Let’s talk about '+p.title)}">Let’s talk about this project ↗</a>`;dialog.showModal();}));
document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});document.querySelectorAll('[data-category]').forEach(p=>p.hidden=button.dataset.filter!=='all'&&p.dataset.category!==button.dataset.filter);}));
document.querySelector('#copy-email').addEventListener('click',async()=>{try{await navigator.clipboard.writeText('younus.koronfel622@gmail.com');document.querySelector('#copy-status').textContent='Email copied.';}catch{document.querySelector('#copy-status').textContent='younus.koronfel622@gmail.com';}});
